const item = $input.first().json.body;
const images = item.images || [];

return images.map(img => ({
  json: {
    article: item.article,
    size: item.size,
    pairs: item.pairs,
    data: item.data,
    filename: img.filename,
    slot: img.slot,
    color: img.color
  },
  binary: {
    file: {
      data: img.base64,
      mimeType: img.filename.toLowerCase().endsWith('.png') ? 'image/png' : 'image/jpeg',
      fileName: img.filename
    }
  }
}));

const item = $input.first().json;
const d = item.data || {};
const uploadedImages = item.uploadedImages || [];

// Categories now arrive as real WooCommerce category IDs (numbers) straight from
// the dashboard's live-fetched CategoryPicker -- see MAFCO CATEGORIES WEBHOOK and
// the dashboard's buildCategoryTree (29 Aug 2026). No lookup table needed here
// anymore -- just validate and pass the IDs straight through.
const categories = (d.categories || [])
  .map(id => Number(id))
  .filter(id => Number.isFinite(id) && id > 0)
  .map(id => ({ id }));

const colorImages = uploadedImages.filter(img => img.id && img.color);
const colorNames = [...new Set(colorImages.map(img => img.color))];

// Size is now a real per-variation dimension: the dashboard sends a list of
// size groups (e.g. ["7X12", "8X12"]) instead of a single value. Falls back
// to the old single "size" field for backward compatibility.
const sizeGroups = Array.isArray(item.sizes) && item.sizes.length
  ? item.sizes
  : (item.size ? [item.size] : []);

const BRAND_IDS = { "MAFCO": 132, "Kats": 203 };
const brandTerms = (d.brand && BRAND_IDS[d.brand]) ? [{ id: BRAND_IDS[d.brand] }] : [];

const images = uploadedImages
  .filter(img => img.id)
  .map(img => ({ id: img.id }));

const payload = {
  name: d.articleNo,
  type: 'variable',
  status: 'publish',
  sku: d.articleNo,
  catalog_visibility: 'visible',
  reviews_allowed: false,
  short_description: d.shortDescription,
  description: d.longDescription,
  images: images,
  categories: categories,
  attributes: [
    { id: 2, options: colorNames, variation: true, visible: true },
    { id: 5, options: sizeGroups, variation: true, visible: true }
  ],
  brands: brandTerms,
  meta_data: [
    { key: 'rank_math_title', value: d.seoTitle },
    { key: 'rank_math_description', value: d.metaDescription },
    { key: 'rank_math_focus_keyword', value: d.focusKeyword }
  ]
};

return [{
  json: {
    article: item.article,
    articleNo: d.articleNo,
    wc_body: payload,
    colorImages: colorImages,
    sizeGroups: sizeGroups
  }
}];

const original = $('Prepare Woocommerce payload').first().json;
const variationSummary = $('Combine variation results').first().json;

// The parent product response comes from whichever branch actually ran --
// a brand-new product (Create Woocommerce product) or an existing one that
// got updated instead (Update Existing Product). Try both, safely.
let wcResponse = {};
try {
  wcResponse = $('Create Woocommerce product').first().json;
} catch (e) {
  try {
    wcResponse = $('Update Existing Product').first().json;
  } catch (e2) {
    wcResponse = {};
  }
}

const parentError = !!wcResponse.error;
const variationsOk = variationSummary.allVariationsOk !== false;
const isError = parentError || !variationsOk;

return [{
  json: {
    article: original.article,
    status: isError ? 'failed' : 'success',
    productId: wcResponse.id || null,
    url: wcResponse.permalink || null,
    error: parentError ? (wcResponse.error.message || 'Unknown error') : (!variationsOk ? 'One or more variations failed to create' : null),
    variationResults: variationSummary.variationResults || []
  }
}];

const httpResults = $input.all();
const originals = $('Upload all images').all();

const uploaded = httpResults.map((item, i) => ({
  slot: originals[i].json.slot,
  color: originals[i].json.color,
  id: item.json.id
}));

const first = originals[0].json;

return [{
  json: {
    article: first.article,
    size: first.size,
    pairs: first.pairs,
    data: first.data,
    uploadedImages: uploaded
  }
}];

const parent = $input.first().json;
const prep = $('Prepare Woocommerce payload').first().json;
const colorImages = prep.colorImages || [];
const sizeGroups = (prep.sizeGroups && prep.sizeGroups.length)
  ? prep.sizeGroups
  : [prep.sizeGroup || ''];

// existingSkus is only produced on the "found existing variable product" branch
// (via the Merge Attributes node). On the brand-new-product branch that node
// never runs, so referencing it throws -- in that case nothing needs skipping.
let existingSkus = [];
try {
  existingSkus = $('Merge Attributes').first().json.existingSkus || [];
} catch (e) {
  existingSkus = [];
}

const variations = [];
for (const img of colorImages) {
  const colorSlug = (img.color || '').toUpperCase().replace(/[^A-Z0-9]+/g, '');
  for (const size of sizeGroups) {
    const sizeSlug = (size || '').toUpperCase().replace(/[^A-Z0-9]+/g, '');
    const sku = `${prep.articleNo}-${colorSlug}-${sizeSlug}`;
    if (existingSkus.includes(sku)) continue;
    variations.push({
      json: {
        parentId: parent.id,
        articleNo: prep.articleNo,
        color: img.color,
        sizeGroup: size,
        sku,
        imageId: img.id
      }
    });
  }
}
return variations;

const existingProduct = $('Check Product Exists').first().json;
const prep = $('Prepare Woocommerce payload').first().json;
const existingVariations = $input.all().map(item => item.json);

const existingAttrs = existingProduct.attributes || [];
const existingColorAttr = existingAttrs.find(a => a.id === 2);
const existingSizeAttr = existingAttrs.find(a => a.id === 5);

const existingColors = existingColorAttr ? existingColorAttr.options : [];
const existingSizes = existingSizeAttr ? existingSizeAttr.options : [];

const newColors = [...new Set((prep.colorImages || []).map(img => img.color))];
const newSizes = prep.sizeGroups || [];

const mergedColors = [...new Set([...existingColors, ...newColors])];
const mergedSizes = [...new Set([...existingSizes, ...newSizes])];

// Categories also need merging -- the existing product may already be listed
// under one size's category (e.g. "0X2"), and this upload may add another
// (e.g. "3X6"). Without this, the new size's category page never lists it.
const existingCategoryIds = (existingProduct.categories || []).map(c => c.id);
const newCategoryIds = (prep.wc_body && prep.wc_body.categories || []).map(c => c.id);
const mergedCategoryIds = [...new Set([...existingCategoryIds, ...newCategoryIds])];

// Existing variation SKUs -- used downstream to skip recreating variations
// that already exist on this product.
const existingSkus = existingVariations
  .filter(v => v && v.sku)
  .map(v => v.sku);

return [{
  json: {
    productId: existingProduct.id,
    mergedColors,
    mergedSizes,
    mergedCategoryIds,
    existingSkus
  }
}];

