const existing = $('Check Product Exists').first().json;
const prep = $('Prepare Woocommerce payload').first().json;

return [{
  json: {
    article: prep.article,
    status: 'failed',
    error: `Article ${prep.articleNo} already exists as a simple product (ID ${existing.id}, type: ${existing.type}). It needs to be manually converted to a variable product in WooCommerce before a new size can be added. No changes were made.`
  }
}];
